Object.assign(FN_ACT, {
  fnGlForm: t => { const id = t.dataset.k, g = id === 'new' ? { code: '', name: '', type: 'Expense', group: 'Administration', sub: 'Operations', cf: 'Operating', active: true } : fnGl(id); modal(id === 'new' ? 'Add ledger account' : 'Edit account · ' + g.code, `<div class="form-grid">${pcFld('Code (4 digits)', `<input id="gl_code" value="${esc(g.code)}" maxlength="4" ${id === 'new' ? '' : 'disabled'}>`)}${pcFld('Name', `<input id="gl_name" value="${esc(g.name)}">`)}${pcFld('Type', pcSel('gl_type', FN_TYPES, g.type))}${pcFld('Group', `<input id="gl_group" value="${esc(g.group)}" list="gl_groups"><datalist id="gl_groups">${[...new Set(FM().coa.map(x => x.group))].map(x => `<option>${esc(x)}</option>`).join('')}</datalist>`)}${pcFld('Sub-group', `<input id="gl_sub" value="${esc(g.sub)}" list="gl_subs"><datalist id="gl_subs">${[...new Set(FM().coa.map(x => x.sub))].map(x => `<option>${esc(x)}</option>`).join('')}</datalist>`)}${pcFld('Cash-flow class', pcSel('gl_cf', ['Operating', 'Investing', 'Financing', 'Cash'], g.cf))}${pcFld('Status', pcSel('gl_active', [['1', 'Active'], ['0', 'Inactive']], g.active ? '1' : '0'))}</div>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="fnGlOk" data-k="${id}">Save</button>`); },
  fnGlOk: t => { const id = t.dataset.k, code = (v('gl_code') || '').trim(), name = (v('gl_name') || '').trim(); if (!/^\d{4}$/.test(code) || !name) return toast('Enter a 4-digit code and name.', 'bad'); askReason(id === 'new' ? 'Add account' : 'Update account', `${code} ${name}`, async r => { const M = Store.clone(FM()); if (id === 'new') { if (M.coa.some(g => g.code === code)) return toast('Code in use.', 'bad'); M.coa.push({ code, name, type: v('gl_type'), group: v('gl_group'), sub: v('gl_sub'), cf: v('gl_cf'), active: v('gl_active') === '1' }); } else Object.assign(M.coa.find(g => g.code === id), { name, type: v('gl_type'), group: v('gl_group'), sub: v('gl_sub'), cf: v('gl_cf'), active: v('gl_active') === '1' }); M.coa.sort((a, b) => a.code.localeCompare(b.code)); await Store.put('fin', M); fnInvalidate(); audit('Finance', 'Chart of accounts changed', { new: `${code} ${name}`, reason: r }); }); },
  fnProjForm: () => modal('Add project', `<div class="form-grid">${pcFld('Code', '<input id="pj_id" placeholder="PRJ-05">')}${pcFld('Name', '<input id="pj_name">')}${pcFld('Branch', pcSel('pj_bid', [['', 'Head Office']].concat(DATA.branches.filter(b => !b.closed).map(b => [b.id, b.name])), ''))}${pcFld('Budget (₹)', '<input id="pj_budget" type="number" min="0">')}${pcFld('From · to', `<input id="pj_start" type="date" value="${PROC_TODAY}"><input id="pj_end" type="date" value="${pcAddDays(PROC_TODAY, 365)}">`)}</div>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="fnProjOk">Save</button>`),
  fnProjOk: () => { const id = (v('pj_id') || '').trim().toUpperCase(), name = (v('pj_name') || '').trim(); if (!id || !name) return toast('Enter the code and name.', 'bad'); askReason('Add project', name, async r => { const M = Store.clone(FM()); M.projects.push({ id, name, bid: v('pj_bid'), budget: +v('pj_budget') || 0, start: v('pj_start'), end: v('pj_end'), status: 'Active' }); await Store.put('fin', M); audit('Finance', 'Project added', { new: `${id} ${name}`, reason: r }); }); },
  fnCurAdd: () => { const code = (v('cur_code') || '').trim().toUpperCase(), rate = +v('cur_rate'); if (!code || !(rate > 0)) return toast('Enter the code and rate.', 'bad'); askReason('Update exchange rate', `${code} = ₹${rate}`, async r => { const M = Store.clone(FM()); const ex = M.currencies.find(x => x.code === code); if (ex) ex.rate = rate; else M.currencies.push({ code, name: v('cur_name') || code, rate }); await Store.put('fin', M); audit('Finance', 'Exchange rate updated', { new: `${code} ${rate}`, reason: r }); }); },
  fnApprForm: t => { const id = t.dataset.k, a = id === 'new' ? { type: 'Manual journal', entity: '', bid: '', dept: '', from: 0, to: null, levels: ['Finance Manager'] } : FM().approvals.find(x => x.id === id); modal(id === 'new' ? 'Add approval rule' : 'Edit rule ' + a.id, `<div class="form-grid">${pcFld('Transaction type', pcSel('ap_type', ['Manual journal', 'Vendor payment', 'Write-off / bad debt', 'Credit note / refund', 'Period reopen', 'Vendor onboarding', 'Bank adjustment', 'Purchase request', 'Work order', 'High-value payment'], a.type))}${pcFld('Entity', pcSel('ap_entity', [['', 'All']].concat(FM().entities.map(e => [e.id, e.name])), a.entity || ''))}${pcFld('Branch', pcSel('ap_bid', [['', 'All branches']].concat(DATA.branches.filter(b => !b.closed).map(b => [b.id, b.name])), a.bid || ''))}${pcFld('Department', `<input id="ap_dept" value="${esc(a.dept || '')}" placeholder="All">`)}${pcFld('From (₹) · up to (₹, blank = no limit)', `<input id="ap_from" type="number" min="0" value="${a.from || 0}"><input id="ap_to" type="number" min="0" value="${a.to == null ? '' : a.to}">`)}${pcFld('Approval levels (in order)', `<select id="ap_levels" multiple size="6">${['Principal', 'Zonal Director', 'Regional Director', 'Finance Manager', 'Finance Admin', 'CFO', 'CEO'].map(l => `<option ${a.levels.includes(l) ? 'selected' : ''}>${l}</option>`).join('')}</select>`)}</div>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="fnApprOk" data-k="${id}">Save</button>`); },
  fnApprOk: t => { const id = t.dataset.k, levels = [...document.getElementById('ap_levels').selectedOptions].map(o => o.value); if (!levels.length) return toast('Select at least one approval level.', 'bad'); const o = { type: v('ap_type'), entity: v('ap_entity'), bid: v('ap_bid'), dept: v('ap_dept'), from: +v('ap_from') || 0, to: v('ap_to') === '' ? null : +v('ap_to'), levels }; askReason(id === 'new' ? 'Add approval rule' : 'Update approval rule', `${o.type} · ${levels.join(' → ')}`, async r => { const M = Store.clone(FM()); if (id === 'new') M.approvals.push(Object.assign({ id: 'AP' + (M.approvals.length + 1) }, o)); else Object.assign(M.approvals.find(x => x.id === id), o); await Store.put('fin', M); audit('Finance', 'Approval matrix changed', { new: `${o.type} ${INR(o.from)}–${o.to == null ? '∞' : INR(o.to)} · ${levels.join(' → ')}`, reason: r }); }); },
  fnApprDel: t => askReason('Remove approval rule', t.dataset.k, async r => { const M = Store.clone(FM()); M.approvals = M.approvals.filter(x => x.id !== t.dataset.k); await Store.put('fin', M); audit('Finance', 'Approval rule removed', { old: t.dataset.k, reason: r }); }),
  fnCfgSave: t => { const M = Store.clone(FM()), c = M.cfg, k = t.dataset.k, old = JSON.stringify(k === 'rules' ? M.rules : k === 'modes' ? M.modes : c); if (k === 'rules') Object.keys(M.rules).forEach(r => { const d = document.getElementById('rl_dr_' + r), cr = document.getElementById('rl_cr_' + r), on = document.getElementById('rl_on_' + r); if (d && !d.disabled) M.rules[r].dr = d.value; if (cr && !cr.disabled) M.rules[r].cr = cr.value; if (on) M.rules[r].on = on.checked; }); else if (k === 'modes') M.modes.forEach((m, i) => { m.gl = v('md_gl' + i) || m.gl; m.chargePct = +v('md_ch' + i) || 0; }); else { Object.assign(c, { manualJvApprovalAbove: +v('ct_jv') || 0, paymentCfoAbove: +v('ct_pay') || 0, depositWithinDays: +v('ct_dep') || 2, cashInHandAlert: +v('ct_cash') || 50000, dupInvoiceCheck: v('ct_dup') === '1', lateFeePct: +v('ct_lf') || 0, lateFeeGraceDays: +v('ct_lg') || 0, reminders: { days: (v('ct_rem') || '').split(',').map(x => +x.trim()).filter(x => !isNaN(x)), channels: (v('ct_ch') || '').split(',').map(x => x.trim()).filter(Boolean) } }); Object.keys(c.numbering).forEach(x => c.numbering[x] = (v('nb_' + x) || x).trim().toUpperCase()); } askReason('Save finance settings', 'Applies to new transactions; automatic postings are re-derived from the rules.', async r => { await Store.put('fin', M); fnInvalidate(); audit('Finance', 'Settings changed (' + k + ')', { old: old.slice(0, 400), new: JSON.stringify(k === 'rules' ? M.rules : k === 'modes' ? M.modes : M.cfg).slice(0, 400), reason: r }); toast('Saved.'); }); },
  fnIoTemplate: async t => { if (!window.XLSX) return; const k = t.dataset.k, wb = XLSX.utils.book_new(); const sheets = { 'Opening balances': [['GL code', 'Account', 'Branch', 'Party', 'Debit', 'Credit'], ['1201', 'Student receivables – current year', 'B01', '', 150000, ''], ['2102', 'Vendor payables', '', 'Deccan Paper Mart', '', 48000]], 'Chart of accounts': [['Code', 'Name', 'Type', 'Group', 'Sub-group', 'Cash-flow class'], ...FM().coa.map(g => [g.code, g.name, g.type, g.group, g.sub, g.cf])], 'Vendor master': [['Name', 'Category', 'GSTIN', 'PAN', 'Bank', 'Terms', 'Contact', 'Mobile', 'Email']], 'Customer master': [['Name', 'Category', 'Entity', 'City', 'GSTIN', 'Terms', 'Contact', 'Mobile', 'Email']], 'Budgets': [['Branch ID', 'Department', 'Cost centre', 'GL code', 'Project', 'Annual budget'], ['B01', '', 'CC-B01-UTL', '5110', '', 240000]], 'Journal template': [['Date', 'Voucher type', 'Narration', 'Branch', 'Cost centre', 'GL code', 'Debit', 'Credit', 'Party'], ['30-09-2026', 'JV', 'Audit fee accrual', '', 'CC-CORP-ADM', '5139', 75000, '', ''], ['30-09-2026', 'JV', 'Audit fee accrual', '', 'CC-CORP-ADM', '2401', '', 75000, '']] }; XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(sheets[k]), k.slice(0, 30)); await saveFile(`MSEA_Finance_${k.replace(/ /g, '_')}_Template.xlsx`, new Blob([XLSX.write(wb, { bookType: 'xlsx', type: 'array' })])); },
  fnIoFile: t => { const file = t.files[0]; if (!file || !window.XLSX) return; const kind = v('io_kind'); const rd = new FileReader(); rd.onload = () => { try { const wb = XLSX.read(new Uint8Array(rd.result), { type: 'array' }), raw = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: '', raw: false }); askReason(`Import ${raw.length} rows – ${kind}`, file.name, async reason => { const M = Store.clone(FM()), tx = Store.clone(FT()); let ok = 0; const g = (o, keys) => { for (const k of Object.keys(o)) if (keys.includes(k.toLowerCase().replace(/[^a-z]/g, ''))) return o[k]; return ''; }; if (kind === 'Chart of accounts') raw.forEach(o => { const code = String(g(o, ['code', 'glcode'])).trim(); if (!/^\d{4}$/.test(code)) return; const ex = M.coa.find(x => x.code === code); const rec = { code, name: g(o, ['name', 'account']), type: g(o, ['type']) || 'Expense', group: g(o, ['group']), sub: g(o, ['subgroup']), cf: g(o, ['cashflowclass', 'cf']) || 'Operating', active: true }; if (ex) Object.assign(ex, rec); else M.coa.push(rec); ok++; }); else if (kind === 'Budgets') raw.forEach(o => { const bid = String(g(o, ['branchid', 'branch'])).trim(), gl = String(g(o, ['glcode', 'gl'])).trim(), amt = rmAmt(g(o, ['annualbudget', 'budget', 'amount'])); if (!gl || !amt) return; const ex = M.budgets.find(b => b.bid === bid && b.gl === gl && (b.project || '') === String(g(o, ['project']) || '')); if (ex) ex.annual = amt; else M.budgets.push({ id: 'FB' + Date.now().toString(36) + ok, bid, dept: g(o, ['department']), cc: g(o, ['costcentre', 'cc']) || `CC-${bid || 'CORP'}-ADM`, gl, project: g(o, ['project']), annual: amt, fy: '2026-27' }); ok++; }); else if (kind === 'Vendor master') raw.forEach(o => { const name = String(g(o, ['name', 'vendor'])).trim(); if (!name) return; tx.vendors.push({ id: 'VN' + Date.now().toString(36) + ok, no: `VEND-${String(tx.vendors.length + 1).padStart(4, '0')}`, name, cat: g(o, ['category']) || 'Supplier', gstin: g(o, ['gstin']), pan: g(o, ['pan']), bank: g(o, ['bank']), terms: g(o, ['terms']) || '30 days credit', contact: g(o, ['contact']), mobile: g(o, ['mobile']), email: g(o, ['email']), docs: 'Imported', status: 'Pending approval', source: 'Import', log: [{ at: nowIso(), by: App.user.name, role: App.user.role, action: 'Imported – awaiting onboarding approval', remark: file.name }] }); ok++; }); else if (kind === 'Customer master') raw.forEach(o => { const name = String(g(o, ['name', 'customer'])).trim(); if (!name) return; tx.customers.push({ id: 'CU' + Date.now().toString(36) + ok, no: `CUST-${String(tx.customers.length + 1).padStart(4, '0')}`, name, cat: g(o, ['category']) || 'Organisation', entity: g(o, ['entity']) || 'MSEWT', city: g(o, ['city']), gstin: g(o, ['gstin']), terms: g(o, ['terms']) || '30 days credit', contact: g(o, ['contact']), mobile: g(o, ['mobile']), email: g(o, ['email']), gl: '1203', status: 'Active', createdAt: nowIso(), log: [] }); ok++; }); else { /* opening balances & journal template → one balanced journal per voucher group */ const groups = {}; raw.forEach((o, i) => { const key = kind === 'Opening balances' ? 'OPEN' : `${g(o, ['date'])}|${g(o, ['narration'])}`; (groups[key] = groups[key] || []).push(o); }); Object.entries(groups).forEach(([key, rows]) => { const lines = rows.map(o => ({ gl: String(g(o, ['glcode', 'gl', 'code'])).trim(), dr: rmAmt(g(o, ['debit', 'dr'])), cr: rmAmt(g(o, ['credit', 'cr'])), party: g(o, ['party']), bid: String(g(o, ['branch', 'branchid'])).trim(), cc: g(o, ['costcentre', 'cc']) })).filter(l => l.gl); if (kind === 'Opening balances') { const dr = lines.reduce((s, l) => s + l.dr, 0), cr = lines.reduce((s, l) => s + l.cr, 0); if (dr !== cr) lines.push({ gl: '3003', dr: cr > dr ? cr - dr : 0, cr: dr > cr ? dr - cr : 0 }); } try { fnJv(tx, { date: kind === 'Opening balances' ? AYS_ISO : rmParseDate(rows[0].Date || g(rows[0], ['date'])) || PROC_TODAY, vtype: 'JV', type: kind === 'Opening balances' ? 'Opening balance' : 'Imported journal', bid: '', cc: lines[0].cc || 'CC-CORP-ADM', narration: kind === 'Opening balances' ? 'Opening balances imported from ' + file.name : String(g(rows[0], ['narration'])), attach: file.name, src: { mod: 'Finance', kind: 'Excel import', id: '', no: file.name }, lines, force: true }); ok += rows.length; } catch (e) { toast(e.message, 'bad'); } }); } tx.imports.unshift({ at: nowIso(), kind, file: file.name, rows: raw.length, ok, by: App.user.name, reason }); await Store.put('fin', M); await fnSave(tx); audit('Finance', 'Excel import – ' + kind, { new: `${file.name} · ${ok}/${raw.length} rows`, reason }); toast(`${ok} rows imported.`); }); } catch (e) { toast('Could not read the file: ' + e.message, 'bad'); } }; rd.readAsArrayBuffer(file); },
  fnExportJson: async () => { const snap = { generated: nowIso(), by: App.user.name, trialBalance: fnTrial(), journals: fnAll().length, ar: { customers: FT().customers.length, invoices: FT().invoices.length }, ap: { vendors: FT().vendors.length, bills: FT().bills.length, payments: FT().payments.length }, banks: FM().banks.map(b => ({ gl: b.gl, bank: b.bank, balance: fnBal(b.gl) })) }; await saveFile(`MSEA_ledger_snapshot_${PROC_TODAY}.json`, new Blob([JSON.stringify(snap, null, 1)], { type: 'application/json' })); audit('Finance', 'Ledger snapshot exported', { new: PROC_TODAY }); }
});
